// Split a webpack bundle from public/ into one file per module under
// src/bundles/<name>/, plus a manifest that lets build-bundle.js reassemble
// it byte-identically. Usage: node scripts/split-bundle.js <bundle.js> [...]
const fs = require("fs");
const path = require("path");
const acorn = require("acorn");

const ROOT = path.join(__dirname, "..");

function findModulesArray(ast) {
    // The modules array is the largest top-level ArrayExpression whose
    // elements are functions (or holes). Search all array expressions.
    let best = null;
    const visit = (node) => {
        if (!node || typeof node.type !== "string") return;
        if (node.type === "ArrayExpression" && node.elements.length > 50) {
            const fns = node.elements.filter((e) => e && (e.type === "FunctionExpression" || e.type === "ArrowFunctionExpression"));
            if (fns.length > node.elements.length / 2 && (!best || node.elements.length > best.elements.length)) best = node;
            return; // don't descend into module bodies
        }
        for (const key of Object.keys(node)) {
            const v = node[key];
            if (Array.isArray(v)) v.forEach(visit);
            else if (v && typeof v.type === "string") visit(v);
        }
    };
    ast.body.forEach(visit);
    return best;
}

const HINT_NOISE = new Set(["use strict", "toString", "prototype", "object", "string", "number", "function", "undefined", "default"]);

function moduleHints(src) {
    const hints = [];
    for (const m of src.matchAll(/\bclass ([A-Za-z_$][\w$]{2,})/g)) hints.push(m[1]);
    for (const m of src.matchAll(/\bfunction ([A-Za-z_$][\w$]{3,})/g)) hints.push(m[1]);
    for (const m of src.matchAll(/\b(?:G[A-Z][A-Za-z]{3,})\b/g)) hints.push(m[0]);
    for (const m of src.matchAll(/"([A-Za-z][A-Za-z0-9 ._/-]{5,40})"/g)) if (!HINT_NOISE.has(m[1])) hints.push(JSON.stringify(m[1]));
    return [...new Set(hints)].slice(0, 8).join(" ");
}

for (const arg of process.argv.slice(2)) {
    const name = path.basename(arg, ".js");
    const bundlePath = path.join(ROOT, "public", name + ".js");
    const outDir = path.join(ROOT, "src", "bundles", name);
    const src = fs.readFileSync(bundlePath, "utf8");
    console.log(`parsing ${name}.js (${(src.length / 1048576).toFixed(1)}MB)...`);
    const ast = acorn.parse(src, { ecmaVersion: "latest" });
    const arr = findModulesArray(ast);
    if (!arr) throw new Error("modules array not found in " + arg);

    fs.rmSync(outDir, { recursive: true, force: true });
    fs.mkdirSync(outDir, { recursive: true });

    const pad = String(arr.elements.length - 1).length;
    const parts = []; // strings (glue) and {id} refs, concatenated = original file
    const index = [];
    let cursor = 0;
    let count = 0;
    for (let i = 0; i < arr.elements.length; i++) {
        const el = arr.elements[i];
        if (!el) continue; // hole: its commas stay in the glue text
        const id = String(i).padStart(pad, "0");
        parts.push(src.slice(cursor, el.start), { id });
        cursor = el.end;
        const body = src.slice(el.start, el.end);
        fs.writeFileSync(path.join(outDir, id + ".js"), "module.exports = " + body + ";\n");
        index.push(`- \`${id}\` ${moduleHints(body)}`);
        count++;
    }
    parts.push(src.slice(cursor));

    fs.writeFileSync(path.join(outDir, "manifest.json"), JSON.stringify({ bundle: name + ".js", moduleCount: count, parts }, null, 1));
    fs.writeFileSync(
        path.join(outDir, "INDEX.md"),
        `# ${name}.js module index\n\nModule id → content hints (regenerated by split-bundle.js)\n\n` + index.join("\n") + "\n"
    );
    console.log(`  ${count} modules -> src/bundles/${name}/`);
}
